creados = 0
actualizados = 0

for datos in LUGARES:
    nombre = datos["nombre"]

    obj, creado = Lugar.objects.update_or_create(
        nombre=nombre,
        defaults={
            "descripcion": datos["descripcion"],
            "direccion": datos["direccion"],
            "comuna": datos["comuna"],
            "categoria": datos["categoria"],
            "imagen_url": datos["imagen_url"],
            "activo": datos["activo"],
        }
    )

    if creado:
        creados += 1
        print(f"[CREADO] {obj.nombre}")
    else:
        actualizados += 1
        print(f"[ACTUALIZADO] {obj.nombre}")

print()
